// This software is released under the MIT License.
// https://opensource.org/licenses/MIT






const src_darknet_DEFAULTS = {
  DARKNET_URL:
    "https://cdn.jsdelivr.net/gh/ml5js/ml5-data-and-models@master/models/darknetclassifier/darknetreference/model.json",
  DARKNET_TINY_URL:
    "https://cdn.jsdelivr.net/gh/ml5js/ml5-data-and-models@master/models/darknetclassifier/darknettiny/model.json",
  IMAGE_SIZE_DARKNET: 256,
  IMAGE_SIZE_DARKNET_TINY: 224,
};

function src_preProcess(img, size) {
  let image;
  if (!(img instanceof src_dist.Tensor)) {
    if (src_isInstanceOfSupportedElement(img)) {
      image = src_dist.browser.fromPixels(img);
    } else if (
      typeof img === "object" &&
      src_isInstanceOfSupportedElement(img.elt)
    ) {
      image = src_dist.browser.fromPixels(img.elt); // Handle p5.js image and video.
    }
  } else {
    image = img;
  }
  const normalized = image.toFloat().div(src_dist.scalar(255));
  let resized = normalized;
  if (normalized.shape[0] !== size || normalized.shape[1] !== size) {
    const alignCorners = true;
    resized = src_dist.image.resizeBilinear(normalized, [size, size], alignCorners);
  }
  const batched = resized.reshape([1, size, size, 3]);
  return batched;
}

class src_Darknet {
  constructor(version) {
    this.version = version;
    switch (this.version) {
      case "reference":
        this.imgSize = src_darknet_DEFAULTS.IMAGE_SIZE_DARKNET;
        break;
      case "tiny":
        this.imgSize = src_darknet_DEFAULTS.IMAGE_SIZE_DARKNET_TINY;
        break;
      default:
        break;
    }
  }

  async load() {
    switch (this.version) {
      case "reference":
        this.model = await src_loadLayersModel(src_darknet_DEFAULTS.DARKNET_URL);
        break;
      case "tiny":
        this.model = await src_loadLayersModel(src_darknet_DEFAULTS.DARKNET_TINY_URL);
        break;
      default:
        break;
    }

    // Warmup the model.
    const result = src_dist.tidy(() =>
      this.model.predict(src_dist.zeros([1, this.imgSize, this.imgSize, 3]))
    );
    await result.data();
    result.dispose();
  }

  async classify(img, topk = 3) {
    const logits = src_dist.tidy(() => {
      const imgData = src_preProcess(img, this.imgSize);
      const predictions = this.model.predict(imgData);
      return src_dist.softmax(predictions);
    });
    return src_gettopkclasses_getTopKClasses(logits, topk, src_DARKNET_CLASSES);
  }
}

async function src_darknet_load(modelConfig) {
  const { version } = modelConfig;
  if (version !== "reference" && version !== "tiny") {
    throw new Error(
      "Please select a version: darknet-reference or darknet-tiny"
    );
  }

  const darknet = new src_Darknet(version);
  await darknet.load();
  return darknet;
}

