class src_SpeechCommands {
  constructor(options) {
    this.options = options;
  }

  async load(url) {
    if (url) {
      const loader = src_modelLoader(url);
      this.model = src_create(
        "BROWSER_FFT",
        undefined,
        loader.modelUrl,
        loader.metadataUrl
      );
    } else this.model = src_create("BROWSER_FFT");
    await this.model.ensureModelLoaded();
    this.allLabels = this.model.wordLabels();
  }

  classify(topk = this.allLabels.length, cb) {
    return this.model
      .listen(async (result) => {
        if (result.scores) {
          const classes = await src_gettopkclasses_getTopKClasses(
            result.scores,
            topk,
            this.allLabels
          );          
          // if classifyStop is called stop the continuous listening
          if (src_instance.signalStop){
            this.model.stopListening();
            src_instance.isClassifying = false;
            return
          } 
          return cb(classes);
        }
        return cb(null, `ERROR: Cannot find scores in result: ${result}`);
      }, this.options)
      .catch((err) => {
        return cb(null, `ERROR: ${err.message}`);
      });
  }
}

async function src_speechcommands_load(options, url) {
  const speechCommandsModel = new src_SpeechCommands(options);
  await speechCommandsModel.load(url);
  return speechCommandsModel;
}

